<script setup lang="ts">
import { ArrowRight, CalendarDays, Clock3, Link2, LogOut, UserRound } from '@lucide/vue'
import { SALON_TIMEZONE,formatXof } from '~~/shared/constants/business'
definePageMeta({middleware:'customer'})
type AccountService={name:string;priceXof:number}
type AccountAppointment={id:string;reference:string;status:string;startsAt:string;totalXof:number;amountPaidXof:number;remainingXof:number;services:AccountService[]}
type AccountData={profile:{firstName:string;lastName:string;phone:string;email:string|null};appointments:AccountAppointment[]}
const{data,error,refresh}=await useFetch<AccountData>('/api/account/appointments',{key:'account-appointments'})
const claimMessage=ref(''),claimError=ref(''),busy=ref(false)
onMounted(async()=>{const token=sessionStorage.getItem('onglerie-guest-token');if(!token)return;busy.value=true;try{const result=await $fetch<{message:string}>('/api/account/claim',{method:'POST',body:{token}});claimMessage.value=result.message;sessionStorage.removeItem('onglerie-guest-token');sessionStorage.removeItem('onglerie-booking-id');await refresh()}catch(e){claimError.value=(e as{data?:{statusMessage?:string}})?.data?.statusMessage||'Impossible de lier cette réservation.'}finally{busy.value=false}})
const upcoming=computed(()=>data.value?.appointments.filter((item)=>new Date(item.startsAt)>=new Date()&&['confirmed','pending_payment'].includes(item.status))??[])
const past=computed(()=>data.value?.appointments.filter((item)=>!upcoming.value.some((up)=>up.id===item.id))??[])
function date(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'full',timeStyle:'short'}).format(new Date(value))}
function serviceNames(items:AccountService[]){return items.map((item)=>item.name).join(' · ')}
async function logout(){await $fetch('/api/auth/sign-out',{method:'POST'});await navigateTo('/connexion')}
useSeoMeta({title:'Mon compte — Votre onglerie',description:'Retrouvez votre profil et vos rendez-vous.',robots:'noindex,nofollow'})
</script>
<template><div class="container-page account-page"><div class="account-hero"><div><span class="eyebrow">Mon espace</span><h1 class="display">Bonjour, {{data?.profile.firstName||'et bienvenue'}}.</h1><p>Votre espace ne montre que les rendez-vous reliés à votre compte.</p></div><div class="account-actions"><NuxtLink class="btn btn-secondary" to="/mon-compte/profil"><UserRound :size="15"/> Mon profil</NuxtLink><button class="btn btn-secondary" @click="logout"><LogOut :size="15"/> Déconnexion</button></div></div><p v-if="claimMessage" class="account-feedback account-feedback--success" role="status">{{claimMessage}}</p><p v-if="claimError" class="account-feedback" role="alert">{{claimError}}</p><p v-if="busy" class="account-feedback">Liaison sécurisée de votre réservation…</p><div v-if="error" class="empty-state"><p>Reliez une réservation à ce compte avec le lien sécurisé de confirmation pour afficher votre historique.</p><NuxtLink class="btn btn-primary" to="/reservation">Réserver sans compte <ArrowRight :size="15"/></NuxtLink></div><section v-else class="account-section"><div class="section-title"><div><span class="section-kicker">À venir</span><h2 class="display">Vos rendez-vous.</h2></div><NuxtLink class="link-arrow" to="/reservation">Nouvelle réservation <ArrowRight :size="15"/></NuxtLink></div><div v-if="upcoming.length" class="appointment-list"><article v-for="item in upcoming" :key="item.id" class="appointment-card surface-card"><div class="appointment-date"><CalendarDays :size="17"/><span>{{date(item.startsAt)}}</span></div><div><strong>{{serviceNames(item.services)}}</strong><small>Référence {{item.reference}}</small></div><span :class="['status-pill',`status-pill--${item.status==='confirmed'?'confirmed':'pending'}`]">{{item.status==='confirmed'?'Confirmé':'En attente'}}</span><div class="appointment-price"><strong>{{formatXof(item.totalXof)}}</strong><small>Payé {{formatXof(item.amountPaidXof)}} · solde {{formatXof(item.remainingXof)}}</small></div><NuxtLink class="link-arrow" :to="`/mon-compte/rendez-vous/${item.id}`">Détails <ArrowRight :size="14"/></NuxtLink></article></div><div v-else class="empty-state">Aucun rendez-vous à venir n’est rattaché à votre compte.</div><div class="section-title account-past"><div><span class="section-kicker">Historique</span><h2 class="display">Précédemment.</h2></div></div><div v-if="past.length" class="appointment-list"><article v-for="item in past" :key="item.id" class="appointment-card surface-card"><div class="appointment-date"><Clock3 :size="16"/><span>{{date(item.startsAt)}}</span></div><div><strong>{{serviceNames(item.services)}}</strong><small>{{item.reference}}</small></div><span class="status-pill">{{item.status}}</span><div class="appointment-price"><strong>{{formatXof(item.totalXof)}}</strong><small>Encaissé {{formatXof(item.amountPaidXof)}}</small></div><NuxtLink class="link-arrow" :to="`/mon-compte/rendez-vous/${item.id}`">Détails <ArrowRight :size="14"/></NuxtLink></article></div><div v-else class="empty-state">Votre historique apparaîtra ici après un rendez-vous lié.</div><p class="claim-hint"><Link2 :size="15"/> Vous pouvez relier une réservation invitée en revenant sur sa page de confirmation dans le navigateur qui l’a créée.</p></section></div></template>
<style scoped>.account-page{padding:4.5rem 0}.account-hero,.section-title{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem}.account-hero h1{margin:.6rem 0;font-size:clamp(3rem,6vw,5.2rem)}.account-hero p{color:var(--muted);font-size:.8rem}.account-actions{display:flex;gap:.6rem}.section-title{margin:2.5rem 0 1rem}.section-title h2{margin:.35rem 0;font-size:clamp(2.4rem,4vw,3.6rem)}.appointment-list{display:grid;gap:.6rem}.appointment-card{display:grid;grid-template-columns:1fr 1.2fr auto 1fr auto;align-items:center;gap:1rem;padding:1rem}.appointment-card>div:not(.appointment-date){display:grid;gap:.25rem}.appointment-card strong{font-size:.75rem}.appointment-card small{color:var(--muted);font-size:.61rem}.appointment-date{display:flex;align-items:center;gap:.55rem;color:#655751;font-size:.67rem}.appointment-price{text-align:right}.account-past{margin-top:3rem}.claim-hint,.account-feedback{display:flex;align-items:center;gap:.4rem;color:var(--muted);font-size:.67rem}.account-feedback--success{color:#2f674c}.account-past+.appointment-list .appointment-card{opacity:.82}@media(max-width:850px){.appointment-card{grid-template-columns:1fr auto}.appointment-date{grid-column:1/-1}.appointment-price{text-align:left}.account-hero,.section-title{align-items:flex-start;flex-direction:column}.account-actions{flex-wrap:wrap}}</style>
